CREATE DATABASE IF NOT EXISTS company;
USE company;

DROP TABLE IF EXISTS company.projects;
DROP TABLE IF EXISTS company.employees;

-- Create the employees table
CREATE TABLE IF NOT EXISTS company.employees (
  emp_id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  first_name TEXT NOT NULL,
  last_name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  department TEXT NOT NULL,
  bio TEXT NULL
);

-- Create the projects table
-- Includes an array of 'technologies' to practice CockroachDB array functions
CREATE TABLE IF NOT EXISTS company.projects (
  emp_id UUID REFERENCES company.employees (emp_id) ON DELETE CASCADE,
  project_name TEXT NOT NULL,
  technologies TEXT[], -- Array of tech stacks used in the project
  assigned_at TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY (assigned_at, emp_id)
);

